#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void batch_norm_stats_kernel(
    const float* __restrict__ x,
    float* __restrict__ sum_stats,
    float* __restrict__ sq_sum_stats,
    int64_t channels,
    int64_t height,
    int64_t width,
    int64_t elements_per_channel,
    int chunks_per_channel
) {
    const int64_t c = static_cast<int64_t>(blockIdx.x);
    const int64_t chunk = static_cast<int64_t>(blockIdx.y);
    if (c >= channels) {
        return;
    }
    const int64_t chunk_size =
        (elements_per_channel + chunks_per_channel - 1) / chunks_per_channel;
    const int64_t chunk_start = chunk * chunk_size;
    const int64_t chunk_end = min(chunk_start + chunk_size, elements_per_channel);
    if (chunk_start >= chunk_end) {
        return;
    }
    __shared__ float shared_sum[256];
    __shared__ float shared_sq_sum[256];
    const int tid = threadIdx.x;
    const int64_t plane = height * width;
    const int64_t channel_base = c * plane;
    float sum = 0.0f;
    float sq_sum = 0.0f;
    for (int64_t i = chunk_start + static_cast<int64_t>(tid) * 4;
         i < chunk_end;
         i += static_cast<int64_t>(blockDim.x) * 4) {
        const int64_t batch = i / plane;
        const int64_t spatial = i - batch * plane;
        const int64_t offset = batch * channels * plane + channel_base + spatial;
        const int64_t remaining = chunk_end - i;
        if (remaining >= 4 && spatial + 3 < plane &&
            (reinterpret_cast<uintptr_t>(x + offset) & 15u) == 0u) {
            const float4 v = *reinterpret_cast<const float4*>(x + offset);
            sum += v.x + v.y + v.z + v.w;
            sq_sum += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
        } else {
            const float v = x[offset];
            sum += v;
            sq_sum += v * v;
        }
    }
    shared_sum[tid] = sum;
    shared_sq_sum[tid] = sq_sum;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shared_sum[tid] += shared_sum[tid + stride];
            shared_sq_sum[tid] += shared_sq_sum[tid + stride];
        }
        __syncthreads();
    }
    if (tid == 0) {
        atomicAdd(sum_stats + c, shared_sum[0]);
        atomicAdd(sq_sum_stats + c, shared_sq_sum[0]);
    }
}

__global__ void batch_norm_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int64_t* __restrict__ num_batches_tracked,
    const float* __restrict__ sum_stats,
    const float* __restrict__ sq_sum_stats,
    int64_t channels,
    int64_t height,
    int64_t width,
    int64_t elements_per_channel,
    bool training,
    float momentum,
    float eps
) {
    constexpr int norm_chunks_per_channel = 32;
    const int64_t block_id = static_cast<int64_t>(blockIdx.x);
    const int64_t c = block_id / norm_chunks_per_channel;
    const int64_t chunk = block_id % norm_chunks_per_channel;

    __shared__ float shared_mean;
    __shared__ float shared_variance;
    const int tid = threadIdx.x;
    const int64_t plane = height * width;
    const int64_t channel_base = c * plane;
    const int64_t chunk_size =
        (elements_per_channel + norm_chunks_per_channel - 1) /
        norm_chunks_per_channel;
    const int64_t chunk_start = chunk * chunk_size;
    const int64_t chunk_end =
        min(chunk_start + chunk_size, elements_per_channel);

    if (tid == 0) {
        const float mean = training
            ? sum_stats[c] / static_cast<float>(elements_per_channel)
            : running_mean[c];
        float variance;
        if (training) {
            variance =
                sq_sum_stats[c] / static_cast<float>(elements_per_channel)
                - mean * mean;
            if (variance < 0.0f) {
                variance = 0.0f;
            }
            if (chunk == 0) {
                running_mean[c] =
                    (1.0f - momentum) * running_mean[c] + momentum * mean;
                float unbiased_variance = variance;
                if (elements_per_channel > 1) {
                    unbiased_variance =
                        variance *
                        (static_cast<float>(elements_per_channel) /
                         static_cast<float>(elements_per_channel - 1));
                }
                running_var[c] =
                    (1.0f - momentum) * running_var[c]
                    + momentum * unbiased_variance;
                if (c == 0 && num_batches_tracked != nullptr) {
                    *num_batches_tracked += 1;
                }
            }
        } else {
            variance = running_var[c];
        }
        shared_mean = mean;
        shared_variance = variance;
    }
    __syncthreads();

    const float inv_std = rsqrtf(shared_variance + eps);
    const float gamma = weight[c];
    const float beta = bias[c];

    for (int64_t i = chunk_start + static_cast<int64_t>(tid) * 4;
         i < chunk_end;
         i += static_cast<int64_t>(blockDim.x) * 4) {
        const int64_t batch = i / plane;
        const int64_t spatial = i - batch * plane;
        const int64_t offset = batch * channels * plane + channel_base + spatial;
        const int64_t remaining = chunk_end - i;
        if (remaining >= 4 && spatial + 3 < plane &&
            (reinterpret_cast<uintptr_t>(x + offset) & 15u) == 0u &&
            (reinterpret_cast<uintptr_t>(y + offset) & 15u) == 0u) {
            const float4 v = *reinterpret_cast<const float4*>(x + offset);
            float4 out;
            out.x = ((v.x - shared_mean) * inv_std) * gamma + beta;
            out.y = ((v.y - shared_mean) * inv_std) * gamma + beta;
            out.z = ((v.z - shared_mean) * inv_std) * gamma + beta;
            out.w = ((v.w - shared_mean) * inv_std) * gamma + beta;
            *reinterpret_cast<float4*>(y + offset) = out;
        } else {
            const float v = x[offset];
            const float normalized = (v - shared_mean) * inv_std;
            y[offset] = normalized * gamma + beta;
        }
    }
}
void batch_norm_launcher(
    const float* x,
    float* y,
    const float* weight,
    const float* bias,
    float* running_mean,
    float* running_var,
    int64_t* num_batches_tracked,
    int64_t channels,
    int64_t height,
    int64_t width,
    int64_t elements_per_channel,
    bool training,
    float momentum,
    float eps,
    cudaStream_t stream
) {
    const dim3 block(256);
    float* sum_stats = nullptr;
    float* sq_sum_stats = nullptr;

    if (training) {
        C10_CUDA_CHECK(cudaMallocAsync(
            reinterpret_cast<void**>(&sum_stats),
            static_cast<size_t>(channels) * sizeof(float),
            stream));
        C10_CUDA_CHECK(cudaMallocAsync(
            reinterpret_cast<void**>(&sq_sum_stats),
            static_cast<size_t>(channels) * sizeof(float),
            stream));
        C10_CUDA_CHECK(cudaMemsetAsync(
            sum_stats, 0, static_cast<size_t>(channels) * sizeof(float), stream));
        C10_CUDA_CHECK(cudaMemsetAsync(
            sq_sum_stats, 0, static_cast<size_t>(channels) * sizeof(float), stream));

        constexpr int chunks_per_channel = 32;
        const dim3 stats_grid(
            static_cast<unsigned int>(channels),
            static_cast<unsigned int>(chunks_per_channel));
        batch_norm_stats_kernel<<<stats_grid, block, 0, stream>>>(
            x,
            sum_stats,
            sq_sum_stats,
            channels,
            height,
            width,
            elements_per_channel,
            chunks_per_channel);
        C10_CUDA_KERNEL_LAUNCH_CHECK();
        C10_CUDA_KERNEL_LAUNCH_CHECK();
    }

     const dim3 grid(static_cast<unsigned int>(channels * 32));
    batch_norm_kernel<<<grid, block, 0, stream>>>(
        x,
        y,
        weight,
        bias,
        running_mean,
        running_var,
        num_batches_tracked,
        sum_stats,
        sq_sum_stats,
        channels,
        height,
        width,
        elements_per_channel,
        training,
        momentum,
        eps
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    if (training) {
        C10_CUDA_CHECK(cudaFreeAsync(sum_stats, stream));
        C10_CUDA_CHECK(cudaFreeAsync(sq_sum_stats, stream));
    }
}
